mapper.select:
select operation_id, request_id, account_count, tenant_ids, created_at
  from batch.console_user_batch_operation
 where operation_id = #{operationId,typeHandler=io.github.pinpols.batch.console.config.PostgresUuidTypeHandler}
   and actor_username = #{actor}

select operation_id, request_id, account_count, tenant_ids, created_at
  from batch.console_user_batch_operation
 where request_id = #{requestId,typeHandler=io.github.pinpols.batch.console.config.PostgresUuidTypeHandler}
   and actor_username = #{actor}
